/*
 * node_modules/net — node:http-shaped surface on top of the mochinode_net
 * engine plugin (mochinode_net.dll, living in mochi_modules/).
 *
 * Cooperative, single-threaded serve loop: one request at a time, driven
 * from JS.  The native accept is non-blocking, so the loop yields with a
 * short timer between accepts — that keeps the engine's event loop (and a
 * host-driven remote debugger) responsive instead of parking the only
 * thread inside accept().  The native plugin is an engine plugin, the
 * framing lives in lib/http.js.
 */

import { loadNative } from '../mochinode/index.js';
import { parseRequest, makeResponse } from './lib/http.js';
import { setTimeout as osSetTimeout } from 'mbjs:os';

const native = await loadNative('mochinode_net.dll');

export function createServer(handler) {
    const server = {
        handler,

        async listen(port, onListen) {
            const fd = native.httpServer(port);
            if (fd < 0)
                throw new Error('net: listen(' + port + ') failed');
            server.fd = fd;
            if (onListen) onListen();

            while (true) {
                const conn = native.httpAccept(fd);
                if (conn < 0) {
                    /* no pending connection: yield to the engine loop
                       (timers, jobs, and the host's own work) */
                    await new Promise(r => osSetTimeout(r, 5));
                    continue;
                }

                let raw = '';
                const marker = '\r\n\r\n';
                let bodyStart = -1, needBody = 0;
                for (;;) {
                    const chunk = native.httpRead(conn, 16384);
                    if (chunk === undefined) break;
                    raw += chunk;
                    if (bodyStart < 0) {
                        const i = raw.indexOf(marker);
                        if (i < 0) continue;          /* headers not complete */
                        bodyStart = i + 4;
                        const head = raw.slice(0, i);
                        const cl = /content-length:\s*(\d+)/i.exec(head);
                        needBody = cl ? parseInt(cl[1], 10) : 0;
                    }
                    if (raw.length - bodyStart >= needBody) break;   /* body done */
                }

                const req = parseRequest(raw);
                const res = makeResponse(native.httpWrite, conn);

                try {
                    await server.handler(req, res);
                } catch (e) {
                    if (typeof e === 'object' && e && e.message) {
                        res.statusCode = 500;
                        res.json({ error: String(e.message) });
                    }
                } finally {
                    native.httpClose(conn);
                }
            }
        },
    };
    return server;
}

export default { createServer };
